'use strict';
const phases=[
{name:'KENAL PASTI',place:'Peta Risiko',x:17,y:22,tag:'AD01 · 5W1H',title:'Tulis risiko yang boleh dinilai',scenario:'Unit E-Commerce memberi keutamaan kempen kepada sesetengah penjual. Aduan awal hanya menyebut “layanan istimewa”.',question:'Pernyataan risiko manakah paling lengkap dan berguna?',options:['Pegawai mungkin tidak jujur.','Pegawai E-Commerce menerima imbuhan daripada penjual sebagai balasan memberi keutamaan kempen dan featured listing.','Penjual suka meminta layanan istimewa.'],answer:1,explain:'Pernyataan itu menyatakan siapa, perbuatan, pihak terlibat, balasan dan konteks proses. Ia boleh dipadankan dengan punca, impak serta kawalan.',deliverable:'9 risiko operasi dikenal pasti dengan konteks yang jelas.'},
{name:'KLASIFIKASI R/G/I',place:'Meja Taksonomi',x:83,y:22,tag:'CRA01 · KATEGORI',title:'Bezakan jenis risiko',scenario:'Seorang pegawai Perolehan menerima ganjaran untuk membocorkan maklumat sulit tender kepada pembekal.',question:'Apakah kategori utama risiko ini?',options:['Rasuah — ada imbuhan sebagai pertukaran untuk tindakan rasmi.','Tatakelola — hanya kerana SOP mungkin kurang jelas.','Integriti — sekadar isu disiplin tanpa pertukaran manfaat.'],answer:0,explain:'Pertukaran ganjaran dengan maklumat tender ialah elemen rasuah. Tatakelola menumpukan kelemahan sistem; integriti menumpukan salah guna atau pelanggaran nilai tanpa imbuhan yang dinyatakan.',deliverable:'Portfolio risiko dipisahkan kepada Rasuah, Tatakelola dan Integriti.'},
{name:'NILAI RESIDUAL',place:'Makmal Matriks',x:17,y:80,tag:'CRA02 · PENILAIAN',title:'Nilai risiko selepas kawalan',scenario:'Akses dokumen tender telah dihadkan dan audit trail wujud, tetapi semakan akses tidak dibuat secara konsisten. Kesan kebocoran kekal besar.',question:'Bagaimana risiko residual patut dinilai?',options:['Automatik rendah kerana kawalan sudah disenaraikan.','Berdasarkan keberkesanan sebenar kawalan, impak dan kebarangkalian yang masih tinggal.','Sama dengan risiko asal dalam semua keadaan.'],answer:1,explain:'Risiko residual ialah baki risiko selepas mengambil kira keberkesanan kawalan sedia ada. Nama kawalan sahaja tidak membuktikan ia berkesan.',deliverable:'Keutamaan ditentukan melalui impak × kebarangkalian residual.'},
{name:'PILIH RAWATAN',place:'Control Lab',x:83,y:80,tag:'CRA04/05 · INISIATIF',title:'Pilih kawalan yang menyasar punca',scenario:'Bayaran vendor boleh dipercepat atau maklumat pembayaran diubah oleh pegawai Finance. Puncanya termasuk akses luas dan kelulusan yang lemah.',question:'Pakej rawatan manakah paling kuat?',options:['Edarkan poster “Jangan Rasuah” sekali setahun.','Sistem bayaran vendor berjejak, segregation of duties, had akses, kemas kini LOA/SOP dan semakan berkala.','Minta vendor bersabar jika bayaran lambat.'],answer:1,explain:'Gabungan kawalan pencegahan, pengesanan dan tadbir urus menyasar punca proses. Kesedaran sahaja tidak mencukupi untuk akses dan kelulusan berisiko.',deliverable:'Inisiatif tambahan dipadankan dengan punca, pemilik dan keutamaan.'},
{name:'RACI & KPI',place:'Bilik Pelaksanaan',x:50,y:13,tag:'PT01 · PELAN TINDAKAN',title:'Jadikan pelan boleh dilaksanakan',scenario:'HR perlu melaksanakan due diligence pengambilan dan pengisytiharan konflik kepentingan panel temu duga.',question:'Pelan tindakan manakah paling boleh dipantau?',options:['HR buat bila ada masa; KPI: “lebih berintegriti”.','HR bertanggungjawab, Ketua HR accountable, Integrity dirujuk; siap 3 bulan; KPI 100% calon berisiko disemak dan 100% panel mengisytihar COI.','Semua jabatan bertanggungjawab tanpa tarikh atau bukti.'],answer:1,explain:'RACI menjelaskan peranan; tempoh dan KPI yang boleh diukur membolehkan pemantauan. Sasaran mesti mempunyai bukti seperti rekod semakan atau deklarasi.',deliverable:'Pelan 1/3/6/12 bulan mempunyai RACI, pemantauan dan KPI.'}
];
const risks=[['G','Loyalty points'],['G','Data pelanggan'],['G','Pemilihan vendor'],['R','Keutamaan kempen'],['R','Kebocoran tender'],['R','Bayaran vendor'],['I','Akses data IT'],['I','Due diligence HR'],['I','Pakatan sebut harga']];
const $=id=>document.getElementById(id);let progress=0,score=0,attempted=new Set(),firstCorrect=[];
function render(){$('score').textContent=score;$('progressText').textContent=`${progress} / 5 FASA`;$('percent').textContent=`${progress*20}%`;$('bar').style.width=`${progress*20}%`;$('nodes').innerHTML=phases.map((p,i)=>`<button class="node ${i<progress?'done':i===progress?'active':''}" style="left:${p.x}%;top:${p.y}%" data-phase="${i}" ${i>progress?'disabled':''}><span class="num">${i<progress?'✓':i+1}</span><strong>${p.name}</strong><small>${p.place}</small></button>`).join('');document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>visit(+b.dataset.phase));$('checklist').innerHTML=phases.map((p,i)=>`<div class="check ${i<progress?'done':''}"><i>${i<progress?'✓':'○'}</i><span>${p.name}</span></div>`).join('');$('riskStrip').innerHTML=risks.map((r,i)=>`<span class="risk ${r[0].toLowerCase()}"><b>${r[0]}</b>${String(i+1).padStart(2,'0')} · ${r[1]}</span>`).join('');$('phaseLabel').textContent=progress<5?`FASA ${progress+1} / 5`:'PELAN SIAP';$('nextTag').textContent=progress<5?`LANGKAH ${String(progress+1).padStart(2,'0')}`:'BOARD REVIEW';$('nextText').textContent=progress<5?`Buka ${phases[progress].place}.`:'Bentangkan OACP kepada lembaga.';$('continue').innerHTML=(progress<5?'Mulakan fasa':'Lihat laporan')+' <b>↗</b>'}
function visit(i){if(i>progress)return;if(i<progress){showReview(i);return}const p=phases[i];$('agent').classList.add('walk');$('agent').style.left=p.x+'%';$('agent').style.top=p.y+'%';$('location').textContent=p.place;setTimeout(()=>{$('agent').classList.remove('walk');showQuestion(i)},620)}
function showQuestion(i){const p=phases[i];$('modalTag').textContent=`${p.tag} · CABARAN ${i+1}/5`;$('modalBody').innerHTML=`<h2>${p.title}</h2><p class="scenario">${p.scenario}</p><p class="question">${p.question}</p><div class="choices">${p.options.map((o,n)=>`<button class="choice" data-choice="${n}"><b>${'ABC'[n]}.</b> ${o}</button>`).join('')}</div><div id="feedback"></div><p class="muted">${attempted.has(i)?'Cubaan pembelajaran — markah pertama telah ditentukan.':'20 markah untuk jawapan pertama yang tepat.'}</p>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>answer(i,+b.dataset.choice));if(!$('modal').open)$('modal').showModal()}
function answer(i,n){const p=phases[i],first=!attempted.has(i),good=n===p.answer;attempted.add(i);document.querySelectorAll('[data-choice]').forEach(b=>b.disabled=true);document.querySelector(`[data-choice="${n}"]`).classList.add(good?'correct':'wrong');if(good){if(first){score+=20;firstCorrect.push(i)}progress=i+1;render();$('feedback').innerHTML=`<div class="feedback"><h3>${first?'Tepat · +20 markah':'Tepat · fasa dilengkapkan'}</h3><p>${p.explain}</p></div><p><b>OUTPUT:</b> ${p.deliverable}</p><button id="next" class="primary">${progress===5?'Bentangkan pelan':'Simpan & teruskan'} <b>↗</b></button>`;$('next').onclick=()=>{$('modal').close();if(progress===5)showResults()}}else{$('feedback').innerHTML=`<div class="feedback wrong"><h3>Belum tepat.</h3><p>${p.explain}</p></div><button id="retry" class="primary">Cuba semula <b>↻</b></button>`;$('retry').onclick=()=>showQuestion(i)}}
function showReview(i){const p=phases[i];$('modalTag').textContent='MISSION DOSSIER · '+p.tag;$('modalBody').innerHTML=`<h2>${p.name}</h2><p>${p.deliverable}</p><div class="feedback"><h3>Prinsip utama</h3><p>${p.explain}</p></div><button id="back" class="primary">Kembali ke war room</button>`;$('back').onclick=()=>$('modal').close();$('modal').showModal()}
function showResults(){const rank=score>=80?'Board-ready OACP':score>=60?'Pelan kukuh, beberapa keputusan perlu diasah':'Pelan siap, kefahaman perlu diperkukuh';$('modalTag').textContent='BOARD REVIEW · LAPORAN AKHIR';$('modalBody').innerHTML=`<h2>${rank}</h2><div class="result">${score}<small>/100</small></div><p>Anda membina rantaian lengkap daripada risiko kepada tindakan yang boleh dipantau.</p><div class="feedback"><h3>Kerangka OACP Vertex</h3><p><b>Visi:</b> organisasi e-dagang dipercayai dan inovatif melalui kawalan telus serta berintegriti.</p></div>${phases.map((p,i)=>`<span class="pill">${i+1}. ${p.name} ✓</span>`).join('')}<p><b>3 bidang keutamaan:</b> Operasi · Perolehan & Kewangan · Pentadbiran</p><button id="review" class="primary">Semak semua prinsip <b>↗</b></button><button id="restart" class="choice" style="margin-top:9px">Main semula</button>`;$('review').onclick=showAll;$('restart').onclick=restart;if(!$('modal').open)$('modal').showModal()}
function showAll(){$('modalTag').textContent='ULANG KAJI · 5 FASA';$('modalBody').innerHTML='<h2>Daripada risiko kepada pelaksanaan</h2>'+phases.map((p,i)=>`<div class="feedback"><h3>${i+1}. ${p.name} ${firstCorrect.includes(i)?'· +20':'· latihan'}</h3><p>${p.explain}</p><p><b>Output:</b> ${p.deliverable}</p></div>`).join('')+'<button id="resultBack" class="primary">Kembali ke laporan</button>';$('resultBack').onclick=showResults;$('modal').scrollTop=0}
function restart(){progress=0;score=0;attempted=new Set();firstCorrect=[];$('modal').close();$('agent').style.left='50%';$('agent').style.top='51%';$('location').textContent='Bilik Gerakan';render();$('intro').showModal()}
$('continue').onclick=()=>progress<5?visit(progress):showResults();$('close').onclick=()=>$('modal').close();$('start').onclick=()=>$('intro').close();$('help').onclick=()=>$('intro').showModal();render();$('intro').showModal();
